frappe.ui.form.on('Event', {
    refresh: function(frm) {
        frm.set_query('accessories', 'custom_accessories', function(doc, cdt, cdn) {
            let row = locals[cdt][cdn];
            return {
                filters: {
                    'item_group': row.accessories_type
                }
            };
        });

        function calculate_amount(frm) {
            if (frm.doc.starts_on && frm.doc.ends_on && frm.doc.custom_rate) {
                let start = new Date(frm.doc.starts_on);
                let end = new Date(frm.doc.ends_on);
                let diff_ms = end - start;
                let hours = diff_ms / (1000 * 60 * 60);
                let amount = frm.doc.custom_event_charges === "Hourly" ? hours * frm.doc.custom_rate : hours * frm.doc.custom_daywise_rate;
                frm.set_value('custom_amount', Math.round(amount * 100) / 100);
                frm.refresh_field('custom_amount');
            } else {
                frm.set_value('custom_amount', 0);
                frm.refresh_field('custom_amount');
            }
        }

        function calculate_final_amount(frm) {
            calculate_amount(frm);

            let total_accessories_amount = 0;

            if (frm.doc.custom_accessories) {
                frm.doc.custom_accessories.forEach(function(row) {
                    if (row.amount) {
                        total_accessories_amount += row.amount;
                    }
                });
            }

            let custom_amount = frm.doc.custom_amount || 0;
            let final_amount = custom_amount + total_accessories_amount;

            frm.set_value('custom_final_amount', Math.round(final_amount * 100) / 100);
            frm.refresh_field('custom_final_amount');
        }

        frm.set_query('custom_room', function() {
            return {
                filters: {}
            };
        });

        frm.cscript.custom_room = function(frm) {
            if (frm.doc.custom_room) {
                let field_to_fetch = frm.doc.custom_event_charges === "Hourly" ? 'custom_rate' : 'custom_daywise_rate';
                frappe.db.get_value('URY Room', frm.doc.custom_room, field_to_fetch, function(value) {
                    let rate = value && value[field_to_fetch] ? value[field_to_fetch] : 0;
                    frm.set_value('custom_rate', rate);
                    setTimeout(function() {
                        calculate_amount(frm);
                        calculate_final_amount(frm);
                    }, 200);
                });
            } else {
                frm.set_value('custom_rate', 0);
                setTimeout(function() {
                    calculate_amount(frm);
                    calculate_final_amount(frm);
                }, 200);
            }
        };

        frm.cscript.custom_event_charges = function(frm) {
            frm.cscript.custom_room(frm);
        };

        frm.cscript.starts_on = function(frm) {
            setTimeout(function() {
                calculate_amount(frm);
                calculate_final_amount(frm);
            }, 100);
        };

        frm.cscript.ends_on = function(frm) {
            setTimeout(function() {
                calculate_amount(frm);
                calculate_final_amount(frm);
            }, 100);
        };

        frm.cscript.custom_rate = function(frm) {
            setTimeout(function() {
                calculate_amount(frm);
                calculate_final_amount(frm);
            }, 100);
        };

        setTimeout(function() {
            calculate_amount(frm);
            calculate_final_amount(frm);
        }, 500);
    },

    starts_on: function(frm) {
        calculate_amount_and_final(frm);
        check_event_overlap(frm);
    },

    ends_on: function(frm) {
        calculate_amount_and_final(frm);
        check_event_overlap(frm);
    },

    custom_rate: function(frm) {
        calculate_amount_and_final(frm);
    },

    custom_event_charges: function(frm) {
        if (frm.doc.custom_room) {
            let field_to_fetch = frm.doc.custom_event_charges === "Hourly" ? 'custom_rate' : 'custom_daywise_rate';
            frappe.db.get_value('URY Room', frm.doc.custom_room, field_to_fetch, function(value) {
                let rate = value && value[field_to_fetch] ? value[field_to_fetch] : 0;
                frm.set_value('custom_rate', rate);
                calculate_amount_and_final(frm);
                check_event_overlap(frm);
            });
        } else {
            frm.set_value('custom_rate', 0);
            calculate_amount_and_final(frm);
        }
    },

    custom_room: function(frm) {
        if (frm.doc.custom_room) {
            let field_to_fetch = frm.doc.custom_event_charges === "Hourly" ? 'custom_rate' : 'custom_daywise_rate';
            frappe.db.get_value('URY Room', frm.doc.custom_room, field_to_fetch, function(value) {
                let rate = value && value[field_to_fetch] ? value[field_to_fetch] : 0;
                frm.set_value('custom_rate', rate);
                calculate_amount_and_final(frm);
                check_event_overlap(frm);
            });
        } else {
            frm.set_value('custom_rate', 0);
            calculate_amount_and_final(frm);
        }
    }
});

function check_event_overlap(frm) {
    if (!frm.doc.starts_on || !frm.doc.ends_on || !frm.doc.custom_room) {
        return;
    }

    let current_event_name = frm.doc.name || '';

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Event',
            filters: {
                'status': 'Open',
                'custom_room': frm.doc.custom_room,
                'name': ['!=', current_event_name]
            },
            fields: ['name', 'subject', 'starts_on', 'ends_on', 'custom_room'],
            limit_page_length: 0
        },
        callback: function(response) {
            if (response.message) {
                let overlapping_events = [];
                let current_start = new Date(frm.doc.starts_on);
                let current_end = new Date(frm.doc.ends_on);

                response.message.forEach(function(event) {
                    if (event.starts_on && event.ends_on) {
                        let event_start = new Date(event.starts_on);
                        let event_end = new Date(event.ends_on);

                        if (current_start < event_end && event_start < current_end) {
                            overlapping_events.push({
                                name: event.name,
                                subject: event.subject || 'Untitled Event',
                                starts_on: event.starts_on,
                                ends_on: event.ends_on
                            });
                        }
                    }
                });

                if (overlapping_events.length > 0) {
                    let message = `<div style="color: #d73527; font-weight: bold;">⚠️ Event Overlap Warning!</div><br>`;
                    message += `The selected time slot overlaps with the following open event(s) in room <strong>${frm.doc.custom_room}</strong>:<br><br>`;

                    overlapping_events.forEach(function(event) {
                        let start_formatted = moment(event.starts_on).format('DD-MM-YYYY HH:mm');
                        let end_formatted = moment(event.ends_on).format('DD-MM-YYYY HH:mm');
                        message += `• <strong>${event.subject}</strong> (${event.name})<br>`;
                        message += `&nbsp;&nbsp;📅 ${start_formatted} to ${end_formatted}<br><br>`;
                    });

                    message += `<small style="color: #666;">Please adjust your event timing or choose a different room to avoid conflicts.</small>`;

                    frappe.msgprint({
                        title: 'Event Overlap Detected',
                        message: message,
                        indicator: 'orange'
                    });
                }
            }
        },
        error: function(error) {
            console.error('Error checking event overlap:', error);
        }
    });
}

function calculate_amount_and_final(frm) {
    if (frm.doc.starts_on && frm.doc.ends_on && frm.doc.custom_rate) {
        let start = new Date(frm.doc.starts_on);
        let end = new Date(frm.doc.ends_on);
        let diff_ms = end - start;
        let hours = diff_ms / (1000 * 60 * 60);
        let amount = frm.doc.custom_event_charges === "Hourly" ? hours * frm.doc.custom_rate : hours * frm.doc.custom_daywise_rate;
        frm.set_value('custom_amount', Math.round(amount * 100) / 100);
    } else {
        frm.set_value('custom_amount', 0);
    }

    setTimeout(function() {
        let total_accessories_amount = 0;

        if (frm.doc.custom_accessories) {
            frm.doc.custom_accessories.forEach(function(row) {
                if (row.amount) {
                    total_accessories_amount += row.amount;
                }
            });
        }

        let custom_amount = frm.doc.custom_amount || 0;
        let final_amount = custom_amount + total_accessories_amount;

        frm.set_value('custom_final_amount', Math.round(final_amount * 100) / 100);
    }, 100);
}

frappe.ui.form.on('Accessories', {
    accessories: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.accessories) {
            frappe.db.get_value('Item', row.accessories, 'valuation_rate', function(value) {
                if (value && value.valuation_rate) {
                    frappe.model.set_value(cdt, cdn, 'rate', value.valuation_rate);
                } else {
                    frappe.model.set_value(cdt, cdn, 'rate', 0);
                }
                calculate_row_amount(frm, cdt, cdn);
            });
        } else {
            frappe.model.set_value(cdt, cdn, 'rate', 0);
            calculate_row_amount(frm, cdt, cdn);
        }
    },

    qty: function(frm, cdt, cdn) {
        calculate_row_amount(frm, cdt, cdn);
    },

    rate: function(frm, cdt, cdn) {
        calculate_row_amount(frm, cdt, cdn);
    },

    custom_accessories_remove: function(frm) {
        setTimeout(function() {
            calculate_final_amount_from_child(frm);
        }, 100);
    }
});

function calculate_row_amount(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    let qty = row.qty || 0;
    let rate = row.rate || 0;
    let amount = qty * rate;

    frappe.model.set_value(cdt, cdn, 'amount', Math.round(amount * 100) / 100);

    setTimeout(function() {
        calculate_final_amount_from_child(frm);
    }, 100);
}

function calculate_final_amount_from_child(frm) {
    let total_accessories_amount = 0;

    if (frm.doc.custom_accessories) {
        frm.doc.custom_accessories.forEach(function(row) {
            if (row.amount) {
                total_accessories_amount += row.amount;
            }
        });
    }

    let custom_amount = frm.doc.custom_amount || 0;
    let final_amount = custom_amount + total_accessories_amount;

    frm.set_value('custom_final_amount', Math.round(final_amount * 100) / 100);
    frm.refresh_field('custom_final_amount');
}

frappe.ui.form.on('Sales Invoice', {
    customer: function(frm) {
        frm.set_query('custom_branch', function() {
            return {
                filters: {
                    customer_name: frm.doc.customer
                }
            };
        });
    }
});

frappe.ui.form.on('Customer Branch', {
    customer_name: function(frm) {
        if (frm.doc.customer_name) {
            frappe.call({
                method: "frappe.contacts.doctype.address.address.get_default_address",
                args: {
                    doctype: "Customer",
                    name: frm.doc.customer_name
                },
                callback: function(r) {
                    if (r.message) {
                        frappe.call({
                            method: "frappe.contacts.doctype.address.address.get_address_display",
                            args: {
                                address_dict: r.message
                            },
                            callback: function(res) {
                                if (res.message) {
                                    // Convert <br> tags to newlines
                                    let clean_address = res.message.replace(/<br\s*\/?>/gi, "\n");
                                    frm.set_value("billing_address", clean_address.trim());
                                }
                            }
                        });
                    } else {
                        frm.set_value("billing_address", "");
                    }
                }
            });
        }
    }
});

