frappe.ui.form.on("Sales Order", {
    custom_branch: function(frm) {
        frm.trigger("set_customer_addresses");
    },
    custom_parent_customer_address: function(frm) {
        frm.trigger("set_customer_addresses");
    },
    custom_branch_customer_address: function(frm) {
        frm.trigger("set_customer_addresses");
    },

    set_customer_addresses: function(frm) {
        if (!frm.doc.custom_branch) {
            frm.set_value("shipping_address", "");
            frm.set_value("custom_customer_address_new", "");
            return;
        }

        // Always set shipping_address from branch
        frappe.db.get_value("Customer Branch", frm.doc.custom_branch, "delivery_address")
            .then(r => {
                if (r && r.message && r.message.delivery_address) {
                    frm.set_value("shipping_address", r.message.delivery_address);

                    // Now handle custom_customer_address_new
                    if (frm.doc.custom_parent_customer_address) {
                        // Case 1: Parent customer default address
                        if (frm.doc.customer) {
                            frappe.call({
                                method: "frappe.contacts.doctype.address.address.get_default_address",
                                args: {
                                    doctype: "Customer",
                                    name: frm.doc.customer
                                },
                                callback: function(r) {
                                    if (r.message) {
                                        frappe.call({
                                            method: "frappe.contacts.doctype.address.address.get_address_display",
                                            args: { address_dict: r.message },
                                            callback: function(res) {
                                                if (res.message) {
                                                    let clean_address = res.message.replace(/<br\s*\/?>/gi, "\n");
                                                    frm.set_value("custom_customer_address_new", clean_address.trim());
                                                }
                                            }
                                        });
                                    } else {
                                        frm.set_value("custom_customer_address_new", "");
                                    }
                                }
                            });
                        }
                    } 
                    else if (frm.doc.custom_branch_customer_address) {
                        // Case 2: Branch delivery address
                        frm.set_value("custom_customer_address_new", r.message.delivery_address);
                    } 
                    else {
                        // Case 3: None checked → blank
                        frm.set_value("custom_customer_address_new", "");
                    }
                } else {
                    frm.set_value("shipping_address", "");
                    frm.set_value("custom_customer_address_new", "");
                }
            });
    }
});

